('88ab5971-bf80-dc05-32af-efaa05f7c6b5', 'maire-boundiali', 'Près de 80 % du budget primitif pour 26 projets', 'La mairie a affecté près de 80 % de son budget primitif à la réalisation de 26 projets.', 'https://www.aip.ci/cote-divoire-aip-la-mairie-de-boundiali-alloue-pres-de-80-de-son-budget-primitif-a-la-realisation-de-26-projets/', null, null, 'en_cours', null),
('15dedc0d-e18e-b8d9-8373-0b1f34f276d0', 'maire-dabou', 'Des terrains pour une cité administrative', 'Le conseil municipal a attribué des terrains à six directions régionales pour regrouper leurs services, aujourd''hui dispersés et en location coûteuse.', 'https://www.aip.ci/cote-divoire-aip-la-mairie-de-dabou-met-a-disposition-des-terrains-pour-la-creation-dun-centre-administratif/', '2025-03-05', null, 'en_cours', null),
