('e4a6f00f-c646-07e1-73f5-1a37c9ced36a', 'maire-diabo', 'Une Maison des chefs à Ahougnanou', 'Première pierre posée en juin 2026 : un lieu de concertation, de médiation et de règlement des conflits.', 'https://www.aip.ci/cote-divoire-aip-la-mairie-de-diabo-lance-la-construction-dune-maison-des-chefs-pour-consolider-la-cohesion-sociale/', '2026-06-19', null, 'en_cours', null),
('21d1a209-6577-7a78-566a-8cb696ec609d', 'maire-grand-bassam', 'Construire l''école primaire Jean-Michel Moulod (six classes)', 'Chantier de l''EPP Jean-Michel Moulod, inscrit au budget 2026 de la commune. Avancement de 55 % présenté au conseil municipal du 3 octobre 2026, avec l''école du quartier CAFOP (60 %) et les réhabilitations des EPP Ablé et Petit Paris (50 %).', 'https://www.koaci.com/article/2026/10/05/cote-divoire/societe/cote-divoire-bassam-le-conseil-municipal-se-penche-sur-letat-davancement-des-projets-et-la-planification-de-78-projets-dinvestissement-totalisant-6841-milliards-fcfa_201284.html', '2026-10-05', null, 'en_cours', null),
('61ece7dd-9004-3499-6c2d-d4adfe9fed64', 'maire-grand-bassam', 'Ouvrir la Maison du Tourisme de Grand-Bassam', 'Bâtiment achevé ; embellissement et équipement en cours, inauguration annoncée « dans les tout prochains mois » lors du conseil municipal du 3 octobre 2026.', 'https://www.koaci.com/article/2026/10/05/cote-divoire/societe/cote-divoire-bassam-le-conseil-municipal-se-penche-sur-letat-davancement-des-projets-et-la-planification-de-78-projets-dinvestissement-totalisant-6841-milliards-fcfa_201284.html', '2026-10-05', null, 'en_cours', null),
('4926c040-81b5-bb8e-a0d5-bed7f6fc0056', 'maire-issia', 'Construire le nouvel hôtel de ville d''Issia', 'Travaux annoncés par le maire pour novembre 2026, pour au moins un an. Les services municipaux ont été déplacés (quartier Mira, radio La Voix du Rocher, salle des fêtes, Plateforme de services) pendant le chantier.', 'https://www.aip.ci/cote-divoire-aip-les-services-de-la-mairie-dissia-delocalises-en-prelude-a-la-construction-du-nouvel-hotel-de-ville/', '2026-11-03', '2027-12-01', 'annoncee', null),
('e1e4d5fb-ff17-87fa-3d68-6417a68682ef', 'maire-gbeleban', 'Investir 1,49 milliard FCFA en 2026 dans l''éducation, la santé, l''eau et la voirie', 'Budget primitif 2026 de 1 688 914 000 FCFA adopté le 8 novembre 2025, dont 1 491 275 000 FCFA d''investissement. Priorités : éducation, santé, hydraulique villageoise, voirie et autonomisation des femmes et des jeunes.', 'https://fr.allafrica.com/stories/202511100356.html', '2025-11-08', '2026-12-01', 'en_cours', null),
('eea244d1-f7fe-2178-d3cf-e26131fe6bff', 'maire-divo', 'Ouvrir 102 km de rues dans la ville de Divo', 'Annonce du maire lors de la présentation du budget 2025 (3,2 milliards FCFA), avec la maternité en construction et l''achat d''une niveleuse. Objectif de recettes fiscales porté de 600 millions à 1 milliard FCFA par an.', 'https://www.aip.ci/152948/cote-divoire-aip-le-maire-de-divo-annonce-un-budget-de-3200-milliards-de-f-cfa-pour-2025/', '2025-02-05', null, 'en_cours', null),
('79a51175-d498-ddf5-dee4-e68c4d4f0661', 'maire-katiola', 'Programme triennal 2027-2029 : 80 opérations pour plus de 3,4 milliards FCFA', 'Adopté par le conseil municipal le 20 juillet 2026 : 12 actions et 80 opérations, avec environ 800 millions FCFA de financement prévu chaque année de 2027 à 2029.', 'https://www.aip.ci/cote-divoire-aip-le-conseil-municipal-de-katiola-adopte-le-programme-triennal-2027-2029-dun-cout-de-plus-de-35-milliards-fcfa/', '2026-07-20', '2029-12-01', 'annoncee', null),
('9b0ce4fa-7df1-1b7c-f120-ef894b4fd7d9', 'maire-katiola', 'Équiper le village de N''dana : dispensaire, forage et terrain de football', 'Ouvrages remis par le maire le 20 août 2026, avec des forages à Kationon 3, Moderne Extension, Nagnankaha et Kpéfélé et de nouvelles classes. Un magasin de stockage agricole à N''dana et trois classes au groupe scolaire Dimbékaha restent en cours.', 'https://www.koaci.com/article/2026/08/21/cote-divoire/politique/cote-divoire-katiola-le-maire-thomas-camara-met-a-disposition-des-populations-un-dispensaire-un-forage-et-un-terrain-de-football-a-ndana_199754.html', '2026-08-20', null, 'tenue', null),
('5c6c3b71-a976-e131-5772-687ac12496fc', 'maire-sinfra', 'Passer l''éclairage public de Sinfra aux lampes LED', 'Plus de 200 lampes au sodium remplacées par des LED sur les grands axes. Au conseil municipal du 12 novembre 2026, 12 des 19 projets du budget 2026 étaient proches de 100 % d''exécution ; une nouvelle niveleuse est attendue avant la fin de l''année.', 'https://www.aip.ci/cote-divoire-aip-les-travaux-communaux-de-lexercice-2026-de-la-mairie-de-sinfra-connaissent-un-bon-etat-davancement/', '2026-11-16', null, 'tenue', null),
('d36ea2a6-0ab4-6f8e-77d0-f06820d8938d', 'maire-sinfra', 'Réhabiliter et équiper la bibliothèque municipale de Sinfra', 'Réhabilitation complète annoncée au conseil municipal du 12 novembre 2026, avec la reprise de la radio locale (équipement disponible) et l''illumination du monument du rond-point de Dioulabougou.', 'https://www.aip.ci/cote-divoire-aip-les-travaux-communaux-de-lexercice-2026-de-la-mairie-de-sinfra-connaissent-un-bon-etat-davancement/', '2026-11-16', null, 'en_cours', null),
('b8a0a058-d4e6-52dc-7460-869cb2e1ff4e', 'maire-guiglo', 'Doter Guiglo de deux camions-bennes pour la collecte des ordures', 'Annonce du maire au conseil municipal du 29 janvier 2026 : six véhicules pour les services municipaux en 2026, dont deux camions-bennes, une salle de réunion en huit mois et, à terme, un nouvel hôtel de ville.', 'https://www.aip.ci/electionpresidentielle2025/article.php?id=312827', '2026-01-29', '2026-12-01', 'annoncee', null),
('d11eb2eb-eedd-bd84-b414-d3678778647d', 'maire-toumodi', 'Budget 2026 de plus de 1,3 milliard FCFA : écoles, voirie et centres de santé', 'Budget primitif adopté à l''unanimité le 27 septembre 2025, contre 1,039 milliard en 2025. Priorités : embellir les grandes avenues, réhabiliter et équiper les écoles, reprofiler les voies, moderniser les centres de santé communautaires et renforcer le réseau électrique de certains quartiers.', 'https://www.aip.ci/256820/cote-divoire-aip-le-budget-primitif-2026-de-la-mairie-de-toumodi-adopte-a-plus-de-13-milliard-fcfa/', '2025-09-27', '2026-12-01', 'en_cours', null),
('178f4b60-c79d-eaed-da50-ca941e35b943', 'maire-daoukro', 'Construire des centres de santé et des écoles avec un budget 2026 en hausse de 596 millions', 'Budget primitif 2026 de 1 931 737 000 FCFA annoncé le 6 décembre 2025, contre 1 398 843 000 FCFA en 2025, grâce à un meilleur recouvrement des taxes. Le programme triennal 2026-2028 prévoit des centres de santé, des écoles et le recrutement d''agents municipaux.', 'https://www.aip.ci/289562/cote-divoire-aip-le-budget-primitif-2026-de-la-mairie-de-daoukro-oriente-vers-des-projets-dinfrastructures/', '2025-12-06', '2028-12-01', 'en_cours', null),
('43cec970-de7a-1508-07bf-ca147a664542', 'maire-dimbokro', 'Construire le marché moderne et la nouvelle gare routière de Dimbokro', 'Projets annoncés au conseil municipal de début 2026, avec un centre artisanal et une quarantaine de boutiques. Le démarrage des travaux du marché, prévu le 5 mars 2026, a été reporté à fin avril à la demande des commerçants.', 'https://www.koaci.com/index.php/article/2026/03/01/cote-divoire/societe/cote-divoire-marche-moderne-gare-routiere-centres-sociaux-dimbokro-enclenche-sa-metamorphose-sous-limpulsion-du-maire-adama-coulibaly_194756.html', '2026-03-01', null, 'en_cours', null),
('ad3355b7-753e-4d91-2cab-f3581cdec5d8', 'maire-bouafle', 'Reprofiler les voies et construire des dalots dans les quartiers de Bouaflé', 'Priorité du budget primitif 2026 de 2 239 704 000 FCFA adopté le 14 novembre 2025, avec l''assainissement des caniveaux, l''électrification de campements, la réhabilitation de 24 boxes du marché central et des feux tricolores.', 'https://www.aip.ci/279232/cote-divoire-aip-le-conseil-municipal-de-bouafle-adopte-un-budget-2026-en-hausse-pour-accelerer-les-projets-prioritaires/', '2025-11-14', '2026-12-01', 'en_cours', null),
('ee36a29b-075d-7503-6bd8-074e91282f22', 'maire-tiassale', 'Lancer une flotte d''une quinzaine de taxis communaux à Tiassalé', 'Annonce du maire à la 11e Journée de redevabilité du 22 mai 2026, avec un transport gratuit ou à prix réduit le week-end subventionné par la commune.', 'https://www.aip.ci/cote-divoire-aip-le-maire-assale-tiemoko-annonce-un-centre-commercial-une-flotte-de-taxis-communaux-et-la-gratuite-partielle-du-transport-public-a-tiassale/', '2026-05-22', null, 'annoncee', null),
('9907ed95-8673-a404-edf9-85f61c401065', 'maire-tiassale', 'Construire un centre commercial en centre-ville sur fonds propres', 'Prévu face au commissariat pour attirer banques et commerces. D''abord confié à un privé, le projet sera finalement réalisé par la commune après des retards, a annoncé le maire le 22 mai 2026.', 'https://www.aip.ci/cote-divoire-aip-le-maire-assale-tiemoko-annonce-un-centre-commercial-une-flotte-de-taxis-communaux-et-la-gratuite-partielle-du-transport-public-a-tiassale/', '2026-05-22', null, 'annoncee', null),
('8d9f4586-d89b-c191-5207-fbc8b9c6ada1', 'maire-touba', 'Achever le nouveau marché de Touba', 'Chantier en cours avec boutiques, étals et espaces séparés pour la viande, le poisson et la volaille. Le budget 2027 adopté le 30 octobre 2026 (1,943 milliard FCFA, dont 80 % d''investissement) prévoit aussi une gare routière à côté.', 'https://www.koaci.com/article/2026/11/02/cote-divoire/politique/cote-divoire-touba-mise-sur-19-milliard-de-fcfa-pour-changer-de-visage-en-2027_202184.html', '2026-11-02', null, 'en_cours', null),
('25875263-23d7-0b07-4ecb-bda6ecd29bba', 'maire-touba', 'Proposer les actes d''état civil en ligne sur touba.ci', 'Les habitants peuvent désormais demander leurs actes d''état civil sur le site de la commune. Le centre-ville a aussi reçu un jardin public de 7 620 m².', 'https://www.koaci.com/article/2026/11/02/cote-divoire/politique/cote-divoire-touba-mise-sur-19-milliard-de-fcfa-pour-changer-de-visage-en-2027_202184.html', '2026-11-02', null, 'tenue', null),
('3be26063-6af3-8e34-bc52-340fee670095', 'maire-sassandra', 'Construire une nouvelle gare routière de 10 hectares à Sassandra', 'Coût annoncé de plus de 600 millions FCFA, sur un terrain de 10 hectares déjà acquis, inscrit au plan triennal pour 2026. L''actuelle gare, trop exiguë, est inondée à la saison des pluies.', 'https://www.aip.ci/cote-divoire-aip-une-nouvelle-gare-routiere-sera-construite-a-plus-de-600-millions-de-f-cfa-a-sassandra-maire/', '2025-04-16', '2026-12-01', 'annoncee', null),
('cdcfcaa3-d2a3-2ebe-6663-bd452d115b58', 'maire-tanda', 'Apporter 400 millions FCFA au bitumage de voies de Tanda', 'Contribution municipale inscrite au programme triennal 2027-2029 adopté le 25 juillet 2026 (2,337 milliards FCFA, 67 opérations), avec des postes de santé de premiers secours dans les villages et un réseau communal par Starlink.', 'https://www.aip.ci/cote-divoire-aip-un-programme-triennal-de-plus-de-23-milliards-fcfa-pour-accelerer-son-developpement-a-tanda/', '2026-07-25', '2029-12-01', 'annoncee', null),
('c443b0d0-6635-f3d7-a27d-a8ccb6447452', 'maire-vavoua', 'Construire un hôtel de ville moderne de 350 millions FCFA à Vavoua', 'Bâtiment R+1 de 1 200 m² annoncé au premier conseil municipal de 2026, le 11 avril, avec une livraison promise en 18 mois par l''entreprise chargée des travaux.', 'https://www.aip.ci/cote-divoire-aip-vavoua-un-hotel-de-ville-moderne-de-350-millions-fcfa-bientot-erige-dans-la-ville/', '2026-04-11', '2027-10-01', 'annoncee', null),
('6f500c5e-8dac-0120-cd22-9f0c4fe8cfb0', 'maire-meagui', 'Mobiliser 5,7 milliards FCFA sur cinq ans pour 21 initiatives à Méagui', 'Plan stratégique de développement remis le 5 juin 2026, préparé avec l''ANADER : 5 698 901 000 FCFA à mobiliser sur cinq ans.', 'https://www.aip.ci/cote-divoire-aip-meagui-prevoit-plus-de-56-milliards-fcfa-dinvestissements-dans-son-plan-de-developpement/', '2026-06-05', '2031-06-01', 'annoncee', null),
('25503466-4710-749c-b2b1-97a47e110e02', 'maire-lakota', 'Équiper la mairie de Lakota de véhicules et d''engins sur fonds propres', 'Trois pick-up, un camion-benne et une chargeuse sur pneus, d''une valeur de plus de 225 millions FCFA, remis le 12 octobre 2026 aux services techniques, financiers et à la police municipale.', 'https://www.koaci.com/article/2026/10/13/cote-divoire/societe/cote-divoire-lakota-prince-arthur-dalli-injecte-plus-de-225-millions-fcfa-dans-lequipement-de-la-mairie_201562.html', '2026-10-12', null, 'tenue', null),
('6853a8e7-09e7-62f1-b674-08b0caab1778', 'maire-lakota', 'Financer chaque trimestre une centaine de jeunes porteurs de projets', 'Annonce du maire le 12 octobre 2026 : prêts remboursables sur un an avec deux mois de grâce, et lancement prochain d''une micro-finance pour la jeunesse de la commune.', 'https://www.koaci.com/article/2026/10/13/cote-divoire/societe/cote-divoire-lakota-prince-arthur-dalli-injecte-plus-de-225-millions-fcfa-dans-lequipement-de-la-mairie_201562.html', '2026-10-12', null, 'annoncee', null),
('ad8d7ad2-1b15-ec77-14e7-f99cb7c1d8f1', 'maire-ferkessedougou', 'Payer les frais d''examen d''entrée en sixième de 1 782 élèves', 'Mesure du maire pour l''année scolaire 2025-2026, au profit des élèves des inspections Ferké-Sud et Ferké-Nord.', 'https://www.aip.ci/cote-divoire-aip-le-maire-de-ferkessedougou-ouattara-kaweli-prend-en-charge-les-frais-dentree-en-sixieme-pour-1-782-eleves/', '2025-11-25', null, 'tenue', null),
('81e99783-daec-4150-1621-29acbab0e741', 'maire-bondoukou', 'Découper Bondoukou en neuf zones de salubrité', 'Décidé au premier conseil municipal de 2026, le 7 février : chaque zone est suivie par des agents municipaux et des conseillers pour améliorer la gestion des ordures ménagères.', 'https://www.aip.ci/316444/cote-divoire-aip-bondoukou-la-gestion-durable-des-ordures-menageres-au-rang-des-priorites-du-premier-conseil-municipal-de-2026/', '2026-02-07', null, 'en_cours', null),
('f4af0272-bb87-c6d3-c299-c814b2ab0c3e', 'maire-sarhala', 'Construire l''hôtel de ville et une bibliothèque à Sarhala', 'Chantiers en cours présentés au conseil municipal du 10 mars 2026 (budget 2026 de plus de 1,2 milliard FCFA, dont plus de 86 % d''investissement) : hôtel de ville, auberge municipale, centre culturel avec bibliothèque, dispensaire de Bougounon et réhabilitation de 13 bâtiments d''écoles.', 'https://www.aip.ci/332427/cote-divoire-aip-le-conseil-municipal-de-sarhala-consacre-plus-de-86-du-budget-2026-a-linvestissement/', '2026-03-12', null, 'en_cours', null),
('a1f39c86-0305-5606-5806-e0af97581c9e', 'maire-toulepleu', 'Programme 2027-2029 : 54 projets pour Toulépleu', 'Adopté à l''unanimité le 18 juillet 2026, avec un budget 2026 porté de 1,141 à 1,294 milliard FCFA : éducation, action sociale, voirie, hydraulique et autonomisation des femmes.', 'https://www.fratmat.info/article/2643406/regions/toulepleu-le-budget-de-la-mairie-en-hausse', '2026-07-18', '2029-12-01', 'annoncee', null),
('2c0d88e6-aacd-c761-948d-1e619573f7a2', 'maire-m-bengue', 'Réaliser 23 projets en 2027 à M''Bengué', 'Prévus au budget primitif 2027 adopté le 13 novembre 2026. La commune a aussi reçu un camion-benne et un engin de reprofilage des routes pour la salubrité.', 'https://www.aip.ci/cote-divoire-aip-le-conseil-municipal-de-mbengue-adopte-le-budget-primitif-2027-et-prevoit-23-projets/', '2026-11-13', '2027-12-01', 'annoncee', null),
('621893ee-63c2-49f2-5c49-475024db3a9d', 'vice-premier-ministre-defense', 'Loi de programmation militaire 2026-2030', 'Annoncée pour renforcer les capacités des forces armées face aux défis sécuritaires de la sous-région.', 'https://www.aip.ci/cote-divoire-aip-le-ministre-de-la-defense-annonce-une-loi-de-programmation-militaire-2026-2030-face-aux-defis-terroristes/', '2025-12-12', '2030-01-01', 'annoncee', null),
('197f7c23-7a47-2949-83d0-1347ab9cb37f', 'ministre-hydraulique', 'Plan opérationnel eau et assainissement 2025-2030', 'Plan intégré à une stratégie de 20 764 milliards de FCFA sur 25 ans ; un groupe de travail devait finaliser son financement avant la table ronde des bailleurs de décembre 2025.', 'https://www.aip.ci/aip-financement-de-odd-6-letat-ivoirien-et-ses-partenaires-se-concertent-a-abidjan-sur-le-defi-de-lacces-universel-a-leau-potable-et-a-lassainissement/', '2025-07-04', '2030-01-01', 'en_cours', null),
('61364daa-3483-98e5-1a14-aa47be8b434f', 'ministre-urbanisme', 'Programme présidentiel de logements sociaux', '1 405 logements sociaux et économiques remis symboliquement à Grand-Bassam en février 2025 ; l''État fournit des terrains viabilisés et prend en charge les voiries et réseaux primaires.', 'https://www.aip.ci/cote-divoire-aip-programme-presidentiel-de-logements-sociaux-kone-bruno-appelle-a-une-synergie-dactions-pour-accelerer-sa-mise-en-oeuvre/', '2025-02-21', null, 'en_cours', null),
('f33d77d0-4658-fe3a-28d0-87fbf34f71de', 'ministre-infrastructures', 'Feuille de route du réseau routier 2026-2030', 'Projets routiers structurants inscrits au PND 2026-2030, avec une action coordonnée de tous les acteurs du secteur.', 'https://www.aip.ci/cote-divoire-aip-le-gouvernement-definit-la-nouvelle-feuille-de-route-du-reseau-routier-ivoirien-a-lhorizon-2030/', '2026-05-01', '2030-01-01', 'annoncee', null),
('333f3ae0-898c-c7a5-3541-5ee2d95bc519', 'ministre-jeunesse', '86 000 opportunités d''insertion en 2026', 'Annoncées à la FNER 2026 : emplois directs, stages, formations et financements ; à Abengourou, plus de 3 900 opportunités et 155,2 millions de FCFA pour les activités génératrices de revenus.', 'https://www.aip.ci/electionpresidentielle2025/article.php?id=370704', '2026-06-02', '2026-12-01', 'en_cours', null),
('04573da7-3647-a359-f709-aee466179771', 'ministre-delegue-enseignement-technique', 'Porter l''enseignement technique de 5 % à 15 % des élèves d''ici 2030', 'Sept nouveaux établissements publics de formation professionnelle devaient ouvrir à la rentrée 2025-2026.', 'https://www.aip.ci/cote-divoire-aip-sept-nouveaux-etablissements-publics-de-formation-professionnelle-ouvriront-a-la-rentree-scolaire-2025-2026/', '2025-06-03', '2030-01-01', 'en_cours', null),
('433383a4-388b-eb3c-dfa3-950425bca04b', 'ministre-education', 'Achever 14 lycées d''excellence avec internat pour jeunes filles', 'Annoncé avec le déploiement du PNAPAS dans tous les cycles d''ici 2030.', 'https://www.education.gouv.ci/index.php/Activite/details/331', '2025-03-27', '2030-01-01', 'en_cours', null),
('fb03d06d-7bce-7ffc-dc7d-b519a96c7346', 'ministre-tourisme', 'Réhabiliter les ponts de liane et bâtir un hôtel quatre étoiles à Man', 'Annoncé en septembre 2025 : réhabilitation des sites et des ponts de liane, boutiques, restaurants et espaces de loisirs ; travaux de l''hôtel prévus pour démarrer en janvier 2026.', 'https://www.aip.ci/cote-divoire-aip-de-nouveaux-projets-pour-renforcer-lattractivite-touristique-a-man/', '2025-09-30', '2026-01-01', 'annoncee', null),
('be973377-1671-b10c-d004-a65a8f7fc48d', 'ministre-cohesion-nationale', 'Popote familiale : phase 2026', 'Après une phase pilote auprès de 2 000 ménages, la phase 2026 combine kits, transferts monétaires, formation et subventions pour des activités génératrices de revenus, pour des ménages du Registre social unique.', 'https://solidarite.gouv.ci/actualite/actudetail/popote-familiale-l-instrument-de-la-solidarit-gouv', '2026-04-29', null, 'en_cours', null),
('438ef0b7-c540-f012-3b78-d8387ad3810a', 'ministre-transition-numerique', 'Cinq priorités pour 2026', 'Présentées par le ministre pour accélérer la transformation numérique et l''innovation technologique.', 'https://www.gouv.ci/actualite/transition-numerique-et-innovation-technologique-le-ministre-djibril-ouattara-decline-ses-cinq-priorites-pour-2026-1732', '2025-12-31', '2026-12-01', 'annoncee', null),
('a9fb9974-5c7f-040d-0d5d-bc9cf97b8d05', 'ministre-femme-famille', 'Renforcer les actions pour les femmes, les familles et les enfants en 2026', 'Budget 2026 de 31,26 milliards de FCFA adopté par la commission compétente du Sénat.', 'https://www.aip.ci/cote-divoire-aip-la-ministre-nasseneba-toure-annonce-le-renforcement-des-actions-en-faveur-des-familles-en-2026/', '2025-12-13', '2026-12-01', 'annoncee', null),
('349d4a6b-88c3-104c-643c-91a694a538d9', 'ministre-culture', 'Projet C2D Culture à Bouaké et centre culturel Jacques-Aka', 'Lancé à Bouaké en septembre 2025 pour renforcer l''offre culturelle hors d''Abidjan.', 'https://www.aip.ci/cote-divoire-aip-lancement-du-projet-c2d-culture-a-bouake/', '2025-09-09', null, 'en_cours', null),
('c0337c14-5dac-e731-5c2f-a4cb8eeb4a64', 'ministre-delegue-integration-africaine', 'Des produits bancaires pour les investissements de la diaspora', 'Convention signée avec la BNI : produits spécifiques et accompagnement financier des projets des Ivoiriens de l''extérieur.', 'https://www.aip.ci/cote-divoire-aip-diaspora-le-ministere-delegue-et-la-bni-signent-un-partenariat-pour-faciliter-linvestissement-des-ivoiriens-de-lexterieur/', '2026-03-07', null, 'annoncee', null),
('74d95b2a-3609-d771-132c-0ce8602d998c', 'ministre-environnement', 'Réviser la politique nationale de l''environnement', 'Atelier de validation du 1er au 3 octobre 2025 à Abidjan pour adapter la politique aux défis climatiques.', 'https://www.aip.ci/cote-divoire-aip-la-politique-de-lenvironnement-en-cours-de-revision-pour-repondre-aux-defis-climatiques-actuels/', '2025-10-02', null, 'en_cours', null),
('f1058eef-80ab-f7b5-df72-f735512a32f3', 'ministre-sports', 'Plateforme numérique de gestion des fédérations sportives', 'Projet pilote lancé avec cinq fédérations, avant extension aux autres.', 'https://www.aip.ci/cote-divoire-aip-le-ministere-des-sports-renforce-la-bonne-gouvernance-des-federations-avec-loperationnalisation-dun-outil-digital-de-gestion-de-lecosysteme-sportif/', '2025-11-27', null, 'en_cours', null),
('b6350409-a2af-0944-cb8b-cca3cd370136', 'ministre-delegue-productions-vivrieres', 'Engrais et semences gratuits pour les producteurs vivriers (2PAU-CI)', 'Distribution commencée à Sassandra le 2 mai 2025 pour augmenter la production vivrière et réduire la dépendance aux importations.', 'https://www.aip.ci/cote-divoire-aip-des-engrais-et-des-semences-de-vivriers-distribues-dans-le-cadre-du-projet-gouvernemental-2pau-ci/', '2025-05-08', null, 'en_cours', null),
('034b0bb1-5b2c-1f4c-003f-c3e6d3bb41c7', 'ministre-delegue-affaires-maritimes', 'Ports, sécurité maritime, formation nautique : priorités du budget 2026', 'Priorités défendues à la conférence budgétaire de juillet 2025 pour l''exercice 2026.', 'https://www.aip.ci/cote-divoire-aip-le-ministere-delegue-aux-affaires-maritimes-defend-ses-priorites-pour-lexercice-2026-lors-de-la-conference-budgetaire-annuelle/', '2025-07-31', '2026-12-01', 'annoncee', null),
('cb1916d1-0330-230c-d128-e4c9b918a2ad', 'conseil-regional-san-pedro', 'Programme triennal 2027-2029 : 15,06 milliards de FCFA', 'Adopté en session ordinaire le 20 août 2026 : 27 actions et 134 opérations (dont 41 nouvelles) dans l''éducation, la santé, l''eau potable et la réhabilitation des pistes rurales ; 236 millions de FCFA d''actions financées sur ressources propres (associations, éducation, femmes et jeunes).', 'https://www.aip.ci/cote-divoire-aip-san-pedro-plus-de-15-milliards-fcfa-programmes-pour-accelerer-le-developpement-local-sur-trois-ans/', '2026-08-20', '2029-12-01', 'annoncee', null),
('c11b7525-9587-19fe-2b20-fa12fa5b7adf', 'conseil-regional-la-me', 'Budget 2026 : 5,08 milliards de FCFA pour 89 opérations de terrain', 'Budget primitif 2026 de 6 425 299 000 FCFA adopté le 14 novembre 2025 à Yakassé-Attobrou, en hausse de 29 %. L''investissement (79 %) couvre 25 actions et 89 opérations : éducation, santé, insertion des jeunes, autonomisation des femmes, environnement.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-de-lexercice-2026-du-conseil-regional-de-la-me-adopte-a-plus-de-six-milliards-de-francs-cfa/', '2025-11-14', null, 'annoncee', null),
('da6a71d2-55b9-5f99-7398-95652023e6f9', 'conseil-regional-belier', 'Budget 2027 de 8,68 milliards de FCFA', 'Adopté à l''unanimité le 9 octobre 2026 à Molonou (Tiébissou), en hausse de 1,744 milliard de FCFA par rapport à 2026 (6,937 milliards).', 'https://www.aip.ci/cote-divoire-aip-le-conseil-regional-du-belier-adopte-un-budget-primitif-2027-de-8681-milliards-fcfa-en-hausse-de-1744-milliard-fcfa/', '2026-10-09', null, 'annoncee', null),
('305f3235-cb1e-7d06-e161-150ef26e14c0', 'conseil-regional-indenie-djuablin', 'Livrer 2 500 tables-bancs aux collèges de proximité', 'Quatre collèges de proximité ont ouvert pour l''année 2025-2026 ; 2 500 tables-bancs ont été annoncées pour ces établissements, livraison en attente au 6 octobre 2025. Le budget 2026 adopté ce jour-là atteint 6,64 milliards de FCFA, dont 5,30 milliards d''investissement.', 'https://fr.allafrica.com/stories/202510100538.html', '2025-10-06', null, 'en_cours', null),
('a42254e1-5c68-7d95-ab18-d06332a10cc9', 'conseil-regional-poro', '600 millions de FCFA pour les cantines scolaires en 2026', 'Inscrits au budget primitif 2026 de la région du Poro (7,33 milliards de FCFA, +34,28 %), adopté le 22 novembre 2025 à Korhogo.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-2026-de-la-region-du-poro-en-hausse-de-3428/', '2025-11-22', null, 'annoncee', null),
('c82bc6f3-ffcc-2aa8-7cac-5193a11da80b', 'conseil-regional-agneby-tiassa', 'Programme triennal 2027-2029 : 11,56 milliards de FCFA, dont 4,15 pour l''éducation', 'Adopté à l''unanimité le 5 juin 2026 : 107 opérations (83 reconduites, 24 nouvelles) ; éducation 4,15 milliards, routes 1,1 milliard, eau 630 millions, sécurité 487 millions. Le siège du conseil régional (822 millions) est en construction.', 'https://www.aip.ci/cote-divoire-aip-lagneby-tiassa-adopte-son-programme-triennal-2027-2029-de-plus-de-115-milliards-fcfa/', '2026-06-05', '2029-12-01', 'en_cours', null),
('70f05593-d57d-48bd-6822-8267c16019ff', 'conseil-regional-cavally', 'Programme triennal 2026-2028 : 11,42 milliards de FCFA', 'Adopté le 18 avril 2025 à Guiglo : éducation 4,30 milliards, santé 1,14 milliard, routes 1,09 milliard, électrification 644 millions, eau 611 millions, et 900 millions d''appui direct aux populations. 7,35 milliards sont programmés dès 2026.', 'https://www.aip.ci/cote-divoire-aip-2eme-session-2025-le-conseil-regional-du-cavally-adopte-son-programme-triennal-2026-2028/', '2025-04-18', '2028-12-01', 'en_cours', null),
('723b1438-3755-088a-5604-fc63e7b9dc07', 'conseil-regional-hambol', 'Construire 40 logements sociaux pour les enseignants du Hambol', 'Principe arrêté à la session du 31 octobre 2025 : quatre logements dans chaque localité dotée d''un collège de proximité, avant une extension à toute la région. Le budget primitif 2026 a été fixé à 6,69 milliards FCFA, dont 5,469 milliards d''investissement.', 'https://www.koaci.com/index.php/article/2025/10/31/cote-divoire/societe/cote-divoire-region-du-hambol-un-programme-de-construction-de-40-logements-sociaux-pour-enseignants-lance-le-budget-primitif-2026-arrete-a-6690-milliards-fcfa_191653.html', '2025-10-31', null, 'annoncee', null),
('74b5efcc-160c-0fed-0473-45d799f5949b', 'conseil-regional-bere', 'Réaliser 44 marchés en 2026 : santé, écoles, voirie et eau', 'Budget 2026 de 5 428 716 000 FCFA adopté le 28 février 2026, dont 4,37 milliards d''investissement. Parmi les marchés programmés : 13 en santé (475 millions FCFA), 6 en éducation (220 millions) et 13 en voirie (128 millions).', 'https://www.aip.ci/cote-divoire-aip-le-conseil-regional-du-bere-adopte-un-budget-2026-de-plus-de-54-milliards-fcfa/', '2026-02-28', '2026-12-01', 'en_cours', null),
('08b2a66a-8858-058e-8918-4d3e1547fdc8', 'conseil-regional-haut-sassandra', 'Programme 2026-2028 : 106 projets pour plus de 11 milliards FCFA', 'Adopté à l''unanimité le 17 mai 2025 : 7 actions sur fonds propres (416 millions FCFA) et 99 opérations structurantes (10,842 milliards), financées à 88,79 % par l''État.', 'https://www.aip.ci/cote-divoire-aip-le-conseil-regional-du-haut-sassandra-engage-un-programme-dinvestissements-de-11-milliards-de-fcfa-sur-trois-ans/', '2025-05-17', '2028-12-01', 'en_cours', null),
('94cc726d-34bd-a416-2825-36a9defbbca6', 'conseil-regional-haut-sassandra', 'Livrer deux écoles et un centre de santé dans le département d''Issia', 'Remis les 16, 17 et 19 octobre 2026 : trois classes à Makua (28,3 millions FCFA), trois classes avec bureau à Joachimkro (près de 31 millions) et un centre de santé à Sedibia (52 millions).', 'https://www.koaci.com/article/2026/10/27/cote-divoire/politique/cote-divoire-issia-le-conseil-regional-du-haut-sassandra-livre-deux-ecoles-et-un-centre-de-sante_202032.html', '2026-10-19', null, 'tenue', null),
('d656cde0-857f-97f2-f15e-78ab294cdb2c', 'conseil-regional-worodougou', 'Construire dispensaires et maternités dans les villages du Worodougou', 'Deuxième phase lancée le 11 août 2025 : dispensaire à Suinla, maternité à Lenguèkoro, après le dispensaire de Gbohovo et une école à Teguela. Plus de 30 projets étaient alors en cours dans la région.', 'https://www.aip.ci/cote-divoire-aip-lancement-de-nouveaux-projets-dinfrastructures-dans-la-region-du-worodougou/', '2025-08-11', null, 'en_cours', null),
('035602dc-493b-190a-e17d-14a5b91cffe4', 'conseil-regional-tonkpi', 'Construire le stade de Danané', 'Première phase annoncée à la session du 10 avril 2026 : clôture, pelouse, vestiaires et toilettes. Les phases suivantes prévoient des terrains de sport, une arène de lutte traditionnelle, une piste pour les courses de masques et des tribunes.', 'https://www.aip.ci/cote-divoire-aip-le-conseil-regional-du-tonkpi-engage-de-nouveaux-projets-a-danane/', '2026-04-10', null, 'en_cours', null)
) v(id, office, title, description, source_url, made_at, due_at, status, status_note)
join officials o on o.office_key = v.office
cross join (select id from profiles where handle = 'politique') ed
on conflict (id) do nothing;

insert into promises (id, official_id, title, description, source_url, made_at, due_at, status, status_note, created_by, verified_by)
select v.id::uuid, o.id, v.title, v.description, v.source_url, v.made_at::date, v.due_at::date, v.status::promise_status, v.status_note, ed.id, ed.id
from (values
